const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',folder:'M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',spark:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6z',file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8',code:'m8 7-5 5 5 5m8-10 5 5-5 5M14 4l-4 16',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',arrow:'M5 12h14m-5-5 5 5-5 5',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',close:'m6 6 12 12M6 18 18 6',edit:'m4 16 12-12 4 4L8 20H4zM13 7l4 4',archive:'M3 3h18v5H3zM5 8v13h14V8M10 12h4',menu:'M4 6h16M4 12h16M4 18h16',link:'M9 15l6-6M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0m2 0 2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-5 0',check:'m4 12 5 5L20 6',layers:'m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5'};
const icon=n=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[n]||paths.folder)+'"/></svg>';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
let state,token,route={},models=[],busy=false,dirty=false,selected=new Set(),saveTimer,toastTimer;
const fields=[['role','Role & instructions','You are a product designer and frontend engineer.'],['objective','Objective','What should this project achieve?'],['context','Context & audience','Who is it for, and what exists already?'],['requirements','Requirements','Pages, features, content and interactions…'],['constraints','Constraints','Technology, accessibility, performance or other limits…'],['style','Visual direction','Typography, colours, references and motion…'],['format','Output format','For example: implementation plan, then complete HTML.'],['prompt','Your prompt','Describe what you want to create or change…']];
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000);}
async function api(path,data){const r=await fetch(Vibe.base+'/studio-api/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json','X-Workspace-Token':token||'',Authorization:'Bearer '+Vibe.token},...(data?{body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result;}
async function refresh(){state=await api('state');}
const btn=(text,action,ico='plus',cls='')=>'<button aria-label="'+esc(text||action.replaceAll('-',' '))+'" class="'+cls+'" data-action="'+action+'">'+icon(ico)+text+'</button>';
const project=()=>state.projects.find(p=>p.id===route.id);
const activeProjects=()=>state.projects.filter(p=>p.status!=='archived');
const categoryName=id=>state.categories.find(c=>c.id===id)?.name||'Uncategorised';
function categoryOptions(selectedId='',skip=''){return '<option value="">Uncategorised</option>'+state.categories.filter(c=>c.id!==skip).map(c=>{let p=c,label=c.name,depth=0;while(p.parent&&depth++<12){p=state.categories.find(x=>x.id===p.parent);if(!p)break;label=p.name+' / '+label;}return '<option value="'+esc(c.id)+'" '+(c.id===selectedId?'selected':'')+'>'+esc(label)+'</option>';}).join('');}
function navLink(href,text,ico,active){return '<a class="nav-link '+(active?'active':'')+'" href="'+href+'">'+icon(ico)+'<span>'+esc(text)+'</span></a>';}
function projectNav(p){return '<details '+(route.id===p.id?'open':'')+' data-tree="p-'+p.id+'"><summary>'+icon('layers')+esc(p.name)+icon('chevron')+'</summary><div class="branch">'+[['overview','Overview','grid'],['prompt','Prompt studio','spark'],['files','Files & context','file'],['runs','Run history','clock'],['design','Design studio','code']].map(([tab,text,ico])=>navLink('#/project/'+p.id+'/'+tab,text,ico,route.id===p.id&&route.tab===tab)).join('')+'</div></details>';}
function tree(parent=null,depth=0){if(depth>12)return '';return state.categories.filter(c=>c.parent===parent).map(c=>'<details open data-tree="c-'+c.id+'"><summary>'+icon('folder')+esc(c.name)+icon('chevron')+'</summary><div class="branch">'+tree(c.id,depth+1)+activeProjects().filter(p=>p.category===c.id).map(projectNav).join('')+'</div></details>').join('');}
function chrome(){const old=new Map($$('#sidebar details').map(d=>[d.dataset.tree,d.open]));$('#sidebar').innerHTML='<a class="brand" href="#/dashboard"><span class="brand-mark">'+icon('spark')+'</span><div>Vibe<small>CREATIVE WORKSPACE</small></div></a><div class="nav-scroll">'+navLink('#/dashboard','Dashboard','grid',route.page==='dashboard')+navLink('#/projects','All projects','layers',route.page==='projects')+navLink('#/categories','Categories','folder',route.page==='categories')+'<div class="nav-label">YOUR PROJECTS'+btn('','new-project','plus','small')+'</div>'+tree()+activeProjects().filter(p=>!p.category).map(projectNav).join('')+'<div class="nav-label">WORKSPACE</div>'+navLink('#/connections','Models & connections','settings',route.page==='connections')+navLink('#/archive','Archived projects','archive',route.page==='archive')+'</div><div class="sidebar-footer"><span><i class="dot"></i>Local workspace</span><span>Saved on this computer</span></div>';
$$('#sidebar details').forEach(d=>{if(old.has(d.dataset.tree))d.open=old.get(d.dataset.tree);});$('#sidebar').onclick=e=>{if(e.target.closest('a'))document.body.classList.remove('nav-open');};
$('#topbar').innerHTML='<div class="crumb">'+btn('','toggle-nav','menu','mobile-menu')+icon('layers')+'<a href="#/dashboard">Workspace</a>'+icon('chevron')+'<span>'+esc(project()?.name||({dashboard:'Overview',projects:'Projects',categories:'Categories',connections:'Connections',archive:'Archive'})[route.page]||'Overview')+'</span></div><div class="bar-actions"><a class="connection" href="#/connections">'+(state.settings.keyConfigured?'<i class="dot"></i>':'')+esc(state.settings.provider==='openai'?'OpenAI':'Custom provider')+' · '+(state.settings.keyConfigured?'key configured':'configure')+'</a>'+btn('New project','new-project','plus','small')+'<div class="avatar">AE</div></div>';wireActions();}
function heading(title,description,eyebrow='YOUR WORKSPACE',action=''){return '<div class="heading"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+esc(title)+'</h1><p>'+esc(description)+'</p></div>'+action+'</div>';}
function projectCard(p){return '<a class="project-card" href="#/project/'+p.id+'/overview"><div class="card-top"><span class="project-icon '+(p.brand||'')+'">'+icon(p.brand==='lawyer'?'layers':p.brand==='market'?'spark':'folder')+'</span><span class="tag">'+esc(categoryName(p.category))+'</span></div><h3>'+esc(p.name)+'</h3><p>'+esc(p.description||'A new space for your next idea.')+'</p><div class="card-bottom"><span>'+state.files.filter(f=>f.project===p.id).length+' files · '+state.runs.filter(r=>r.project===p.id).length+' runs</span>'+icon('arrow')+'</div></a>';}
function dashboard(){const active=activeProjects();return heading('A space for your next idea.','Build a brief. Gather context. Explore the design. Make it real.','VIBE / WORKSPACE 01')+'<section class="hero"><div><div class="eyebrow">FROM INTENT TO INTERFACE</div><h2>Good work starts<br>with a clear direction.</h2><p>Bring your projects, files, prompts and design decisions into one continuous workspace.</p>'+btn('Start a project','new-project','plus','primary')+'</div><div class="hero-art"><div class="orbit">'+icon('spark')+'</div><span>01 · CONTEXT</span><span>02 · CREATE</span><span>03 · REFINE</span></div></section><div class="stats">'+[[active.length,'Active projects','layers'],[state.files.length,'Context files','file'],[state.runs.length,'Model runs','spark'],[state.categories.length,'Categories','folder']].map(([n,t,i])=>'<div class="stat"><div><strong>'+n+'</strong><span>'+t+'</span></div>'+icon(i)+'</div>').join('')+'</div><div class="section-head"><h2>Your projects</h2><a class="hint" href="#/projects">View all projects →</a></div><div class="grid">'+active.slice(0,5).map(projectCard).join('')+'<button class="project-card create-card" data-action="new-project">'+icon('plus')+'<h3>Start something new</h3><span class="hint">A blank canvas for your next project</span></button></div><div class="section-head"><h2>Recent activity</h2></div><div class="panel">'+runsList(state.runs.slice(0,5))+'</div>';}
function runsList(runs){return runs.length?runs.map(r=>'<div class="run-row">'+icon('spark')+'<div class="file-name"><strong>'+esc(r.draft.objective||r.draft.prompt?.slice(0,90)||'Model run')+'</strong><small>'+esc(r.model)+' · '+new Date(r.created).toLocaleString()+'</small></div><span class="tag status-'+r.status+'">'+esc(r.status)+'</span><button class="small" data-run="'+r.id+'">View '+icon('arrow')+'</button></div>').join(''):'<div class="empty">'+icon('clock')+'<p>Your model runs will appear here.</p><span class="hint">Create a prompt in a project to get started.</span></div>';}
function projectsPage(archived=false){return heading(archived?'Archived projects':'Every project, in one place.',archived?'Restore a project whenever you want to continue.':'Organise your work by category, then pick up where you left off.')+'<div class="toolbar"><label class="search-field">'+icon('search')+'<input id="project-search" aria-label="Search projects" placeholder="Search projects…"></label><select id="project-filter" aria-label="Filter project category" style="width:auto"><option value="all">All categories</option>'+categoryOptions()+'</select></div><div class="grid" id="project-grid"></div>';}
function projectPage(p){const tab=route.tab;return heading(p.name,p.description,'PROJECT / '+categoryName(p.category),btn('Project settings','edit-project','settings','small'))+'<nav class="tabs">'+[['overview','Overview','grid'],['prompt','Prompt studio','spark'],['files','Files & context','file'],['runs','Run history','clock'],['design','Design studio','code']].map(([k,t,i])=>'<a href="#/project/'+p.id+'/'+k+'" class="'+(tab===k?'active':'')+'">'+icon(i)+t+'</a>').join('')+'</nav>'+(tab==='prompt'?promptPage(p):tab==='files'?filesPage(p):tab==='runs'?'<div class="panel">'+runsList(state.runs.filter(r=>r.project===p.id))+'</div>':tab==='design'?designPage(p):'<div class="two"><div class="panel"><div class="eyebrow">NEXT STEP</div><h2 style="margin-top:14px">Give your idea a direction.</h2><p class="hint">Define the outcome, attach your references, then send a structured prompt to your chosen model.</p><a class="primary" style="display:inline-flex;padding:10px 15px;border-radius:8px" href="#/project/'+p.id+'/prompt">Open prompt studio →</a></div><div class="panel"><div class="eyebrow">DESIGN WORKSPACE</div><h2 style="margin-top:14px">'+(p.brand?'Seven directions. One brand.':'Explore the design library.')+'</h2><p class="hint">'+(p.brand?'Compare variations, tune colours and spacing, and export your design brief.':'Use the existing brand studies as references. Your design drafts are isolated for this project.')+'</p><a href="#/project/'+p.id+'/design">Open Design Studio →</a></div></div><div class="section-head"><h2>Recent runs</h2></div><div class="panel">'+runsList(state.runs.filter(r=>r.project===p.id).slice(0,4))+'</div>');}
function field(k,label,placeholder,value='',large=false){return '<label class="field">'+label+'<textarea name="'+k+'" placeholder="'+esc(placeholder)+'" '+(large?'class="large"':'')+'>'+esc(value)+'</textarea></label>';}
function promptPage(p){const d=p.draft||{},files=state.files.filter(f=>f.project===p.id);return '<div class="prompt-layout"><section class="panel"><div class="section-head" style="margin-top:0"><h2>What are we building?</h2><span class="hint" id="draft-status">Draft saved locally</span></div><form id="prompt-form">'+field('objective','Objective',fields[1][2],d.objective)+field('prompt','Your prompt',fields[7][2],d.prompt,true)+'<details class="advanced" open><summary>Instructions & context</summary><div class="two">'+field('role','Role & instructions',fields[0][2],d.role)+field('context','Context & audience',fields[2][2],d.context)+'</div>'+field('requirements','Requirements',fields[3][2],d.requirements)+'<div class="two">'+field('constraints','Constraints',fields[4][2],d.constraints)+field('style','Visual direction',fields[5][2],d.style)+'</div>'+field('format','Output format',fields[6][2],d.format)+'</details><div class="actions">'+btn('Save draft','save-draft','check')+btn(busy?'Generating…':'Generate with model','generate','spark','primary')+'</div></form></section><aside><section class="panel"><div class="eyebrow">MODEL CONNECTION</div><h3 style="margin-top:15px">'+esc(state.settings.model||'Choose a model')+'</h3><p class="hint">'+esc(state.settings.provider==='openai'?'OpenAI · Responses API':state.settings.base)+'<br>Maximum output: '+state.settings.maxTokens.toLocaleString()+' tokens</p><a class="hint" href="#/connections">Manage connection →</a></section><section class="panel"><h3>Context files</h3><p class="hint">Only checked files are sent with this prompt. Add files of any type to your project; model support varies.</p>'+files.map(f=>'<label class="attachment"><input type="checkbox" data-attach="'+f.id+'" '+(selected.has(f.id)?'checked':'')+' '+(f.type==='stored'?'disabled':'')+'><span>'+esc(f.name)+'<small>'+fileKind(f)+'</small></span></label>').join('')+(!files.length?'<p class="hint">No files attached yet.</p>':'')+'<a class="hint" style="display:block;margin-top:18px" href="#/project/'+p.id+'/files">Manage project files →</a></section><section class="panel"><h3>Before you send</h3><p class="hint">Your prompt and selected files go to the configured provider. Generated text is saved to run history. Code is never executed automatically.</p></section></aside></div><section class="panel" id="live-result"><h2>Latest result</h2>'+(busy?'<div class="loading-line"></div><p class="hint">Your model is working. This may take a few minutes.</p>':resultHTML(state.runs.find(r=>r.project===p.id)))+'</section>';}
function fileKind(f){return f.type==='stored'?'Stored locally · not sent to models':f.type==='image'?'Image · requires a vision model':f.type==='document'?'Document · requires Responses file support':'Text / code · sent as text';}
function filesPage(p){return '<label class="drop-zone" id="drop-zone">'+icon('upload')+'<strong>Bring your references into the project</strong><p class="hint">Drop files here or choose files. All file types accepted · under 50 MB each.</p><input type="file" multiple id="file-input" aria-label="Choose project files"></label><p id="upload-status" class="hint" role="status"></p><div class="panel">'+(state.files.filter(f=>f.project===p.id).map(f=>'<div class="file-row">'+icon('file')+'<div class="file-name"><strong>'+esc(f.name)+'</strong><small>'+formatBytes(f.size)+' · '+fileKind(f)+'</small></div><button class="small" data-file-preview="'+f.id+'">Preview</button><button class="small" data-file="'+f.id+'" aria-label="Download '+esc(f.name)+'">'+icon('download')+'</button><button class="small danger" data-remove="'+f.id+'" aria-label="Remove '+esc(f.name)+'">'+icon('close')+'</button></div>').join('')||'<div class="empty">No files yet. Add a brief, screenshot, document or source file.</div>')+'</div>';}
function formatBytes(n){return n>=1048576?(n/1048576).toFixed(1)+' MB':n>=1024?(n/1024).toFixed(1)+' KB':n+' B';}
function designPage(p){const u='/design-studio.html?project='+encodeURIComponent(p.id)+'&brand='+(p.brand||'lawyer')+'&design=1&page=discover';return (!p.brand?'<div class="info-strip">This project uses the existing brand designs as references. Your edits and notes are saved separately for this project.</div>':'')+'<div class="actions" style="margin-bottom:15px"><a href="'+u+'" target="_blank" rel="noopener">Open full Design Studio ↗</a></div><iframe class="studio-frame" title="Project Design Studio" src="'+u+'"></iframe>';}
function resultHTML(r){return r?'<div class="run-meta"><span class="tag status-'+r.status+'">'+esc(r.status)+'</span><span>'+esc(r.model)+'</span><span>'+new Date(r.created).toLocaleString()+'</span>'+(r.usage?'<span>'+esc(r.usage.total_tokens||r.usage.output_tokens||'')+' tokens</span>':'')+'</div><div class="output-actions actions"><button class="small" data-copy="'+r.id+'">Copy output</button><button class="small" data-export="'+r.id+'">'+icon('download')+'Export Markdown</button></div><pre class="result">'+esc(r.output||'Waiting for response…')+'</pre>':'<div class="empty">'+icon('spark')+'<p>Your next idea starts above.</p></div>';}
function connections(){return heading('Codex. Ready to build.','Use the signed-in Codex subscription through your Workbench.','WORKSPACE / CONNECTIONS')+'<section class="panel settings"><h3>Codex subscription</h3><p>No API key is required. Builds run on this computer and appear in Practice and Workbench history.</p><a href="/account/#build">Check connection and builds →</a><p>Claude and BYOK are not enabled in this version.</p></section>';}

function categories(){return heading('Make room for your work.','Create categories within categories, then organise projects beneath them.','WORKSPACE / CATEGORIES',btn('New category','new-category','plus','primary'))+'<div class="panel">'+state.categories.map(c=>'<div class="category-row">'+icon('folder')+'<div class="file-name"><strong>'+esc(c.name)+'</strong><small>'+(c.parent?'Inside '+esc(categoryName(c.parent)):'Top-level category')+' · '+state.projects.filter(p=>p.category===c.id).length+' projects</small></div><button class="small" data-category-edit="'+c.id+'">'+icon('edit')+'Edit</button><button class="small" data-category-child="'+c.id+'">'+icon('plus')+'Subcategory</button></div>').join('')+'</div>';}
function showDialog(title,body){const d=$('#dialog');d.innerHTML='<div class="dialog-head"><h2>'+esc(title)+'</h2><button type="button" aria-label="Close dialog">'+icon('close')+'</button></div><div class="dialog-body">'+body+'</div>';d.querySelector('header button,.dialog-head button').onclick=()=>d.close();d.showModal();}
function projectDialog(p){showDialog(p?'Project settings':'Start a new project','<form id="project-form"><label class="field">Project name<input name="name" required maxlength="100" value="'+esc(p?.name||'')+'" placeholder="Give your project a name"></label><label class="field">Description<textarea name="description" placeholder="What are you building?">'+esc(p?.description||'')+'</textarea></label><label class="field">Category<select name="category">'+categoryOptions(p?.category)+'</select></label><div class="actions"><button class="primary" type="submit">'+icon('check')+(p?'Save project':'Create project')+'</button>'+(p?'<button type="button" id="archive-project">'+icon('archive')+(p.status==='archived'?'Restore project':'Archive project')+'</button>':'')+'</div></form>');$('#project-form').onsubmit=async e=>{e.preventDefault();try{const n=await api('project',{...Object.fromEntries(new FormData(e.target)),id:p?.id,status:p?.status});await refresh();$('#dialog').close();location.hash='/project/'+n.id+'/overview';render();toast(p?'Project updated':'Project created');}catch(e){toast(e.message);}};if(p)$('#archive-project').onclick=async()=>{try{await api('project',{...p,status:p.status==='archived'?'active':'archived'});await refresh();$('#dialog').close();location.hash='/projects';render();toast(p.status==='archived'?'Project restored':'Project archived');}catch(e){toast(e.message);}};}
function categoryDialog(c,parent=''){showDialog(c?'Edit category':'New category','<form id="category-form"><label class="field">Category name<input name="name" required maxlength="80" value="'+esc(c?.name||'')+'"></label><label class="field">Parent category<select name="parent">'+categoryOptions(c?.parent||parent,c?.id).replace('Uncategorised','Top level')+'</select></label><button class="primary">Save category</button></form>');$('#category-form').onsubmit=async e=>{e.preventDefault();try{await api('category',{...Object.fromEntries(new FormData(e.target)),id:c?.id});await refresh();$('#dialog').close();render();toast('Category saved');}catch(e){toast(e.message);}};}
async function saveDraft(quiet=false){const form=$('#prompt-form'),p=project();if(!form||!p)return;clearTimeout(saveTimer);const draft=Object.fromEntries(new FormData(form));const n=await api('draft',{project:p.id,draft});p.draft=n.draft;dirty=false;const label=$('#draft-status');if(label)label.textContent='Saved on this computer';if(!quiet)toast('Draft saved');}
async function generate(){if(busy)return;await saveDraft(true);const p=project(),id=p.id;busy=true;render();try{const run=await api('run',{project:id,files:[...selected]});await refresh();if(run.projectId){location.href='/practice/?project='+encodeURIComponent(run.projectId);return;}toast(run.status==='complete'?'Result saved to run history':run.status==='incomplete'?'Output reached its limit — saved as incomplete':run.output);}finally{busy=false;if(route.page==='project'&&route.tab==='prompt')render();}}
async function saveSettings(){const form=$('#settings-form');const s=await api('settings',Object.fromEntries(new FormData(form)));state.settings=s;form.elements.key.value='';chrome();return s;}
async function upload(files){const id=project().id;const status=$('#upload-status');let uploaded=0,errors=[];for(const f of files){try{if(f.size>=50*1024*1024)throw Error('Must be under 50 MB');if(status)status.textContent='Uploading '+f.name+'…';const b64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f);});await api('upload',{project:id,name:f.name,data:b64});uploaded++;}catch(e){errors.push(f.name+': '+e.message);}}await refresh();if(route.id===id)render();toast(uploaded+' file'+(uploaded===1?'':'s')+' added'+(errors.length?' · '+errors.join('; '):''));}
async function getFile(id){const r=await fetch(Vibe.base+'/studio-api/file?id='+encodeURIComponent(id),{headers:{'X-Workspace-Token':token,Authorization:'Bearer '+Vibe.token}});if(!r.ok)throw Error('Could not read file');return r.blob();}
function downloadBlob(name,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function previewFile(id){const f=state.files.find(x=>x.id===id),blob=await getFile(id);if(f.type==='text'){showDialog(f.name,'<pre class="result">'+esc(await blob.text())+'</pre>');}else if(f.type==='image'||/\.pdf$/i.test(f.name)){const u=URL.createObjectURL(new Blob([blob],{type:f.type==='image'?f.mime:'application/pdf'}));showDialog(f.name,f.type==='image'?'<img style="max-width:100%" src="'+u+'" alt="'+esc(f.name)+'">':'<iframe title="PDF preview" style="width:100%;height:60vh;border:0" src="'+u+'"></iframe>');$('#dialog').addEventListener('close',()=>URL.revokeObjectURL(u),{once:true});}else showDialog(f.name,'<p class="hint">This file is stored in your project. Download it to preview in its native application.</p>');}
function wireActions(){$$('[data-action]').forEach(b=>b.onclick=async e=>{e.preventDefault();try{const a=b.dataset.action;if(a==='new-project')projectDialog();if(a==='edit-project')projectDialog(project());if(a==='new-category')categoryDialog();if(a==='toggle-nav')document.body.classList.toggle('nav-open');if(a==='save-draft')await saveDraft();if(a==='generate')await generate();if(a==='save-settings'){await saveSettings();toast('Connection saved');}if(a==='clear-key'){await api('settings',{...state.settings,clearKey:true});await refresh();render();toast('Entered key cleared; environment keys remain available');}if(a==='load-models'){b.disabled=true;await saveSettings();models=await api('models');$('#model-list').innerHTML=models.map(m=>'<option value="'+esc(m)+'">').join('');$('#connection-status').textContent=models.length+' models available. Choose one in the Model ID field, then save.';toast('Connection verified · '+models.length+' models');}}catch(e){toast(e.message);}finally{b.disabled=false;}});}
function wire(){wireActions();$$('[data-category-edit]').forEach(b=>b.onclick=()=>categoryDialog(state.categories.find(c=>c.id===b.dataset.categoryEdit)));$$('[data-category-child]').forEach(b=>b.onclick=()=>categoryDialog(null,b.dataset.categoryChild));$$('[data-attach]').forEach(b=>b.onchange=()=>b.checked?selected.add(b.dataset.attach):selected.delete(b.dataset.attach));$$('[data-run]').forEach(b=>b.onclick=()=>{showDialog('Run result',resultHTML(state.runs.find(r=>r.id===b.dataset.run)));wireResults();});wireResults();$$('[data-file]').forEach(b=>b.onclick=async()=>{try{const f=state.files.find(x=>x.id===b.dataset.file);downloadBlob(f.name,await getFile(f.id));}catch(e){toast(e.message);}});$$('[data-file-preview]').forEach(b=>b.onclick=()=>previewFile(b.dataset.filePreview).catch(e=>toast(e.message)));$$('[data-remove]').forEach(b=>b.onclick=()=>{const f=state.files.find(x=>x.id===b.dataset.remove);showDialog('Remove file?','<p>'+esc(f.name)+' will be removed from this project. Previous run records remain.</p><button class="danger" id="confirm-remove">Remove file</button>');$('#confirm-remove').onclick=async()=>{try{await api('remove-file',{id:f.id});selected.delete(f.id);await refresh();$('#dialog').close();render();toast('File removed');}catch(e){toast(e.message);}};});
if($('#project-grid')){const paint=()=>{const q=$('#project-search').value.toLowerCase(),cat=$('#project-filter').value;const items=state.projects.filter(p=>(route.page==='archive'?p.status==='archived':p.status!=='archived')&&(!q||(p.name+' '+p.description).toLowerCase().includes(q))&&(cat==='all'||(p.category||'')===cat));$('#project-grid').innerHTML=items.map(projectCard).join('')||'<div class="empty">No matching projects.</div>';};$('#project-search').oninput=paint;$('#project-filter').onchange=paint;paint();}
if($('#prompt-form')){$('#prompt-form').onsubmit=e=>e.preventDefault();$('#prompt-form').oninput=()=>{dirty=true;$('#draft-status').textContent='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft(true).catch(e=>toast(e.message)),700);};const b=$('[data-action="generate"]');if(b)b.disabled=busy;}
if($('#settings-form')){$('#settings-form').onsubmit=e=>e.preventDefault();const toggle=()=>{const open=$('#provider').value==='openai';$('#base-field').style.display=open?'none':'block';$('#mode').disabled=open;if(open)$('#mode').value='responses';};$('#provider').onchange=toggle;toggle();}
if($('#file-input')){$('#file-input').onchange=e=>upload([...e.target.files]);const zone=$('#drop-zone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag');};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');upload([...e.dataTransfer.files]);};}}
function wireResults(){$$('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(state.runs.find(r=>r.id===b.dataset.copy).output);toast('Output copied');}catch{toast('Clipboard unavailable; select the output text to copy.');}});$$('[data-export]').forEach(b=>b.onclick=()=>{const r=state.runs.find(r=>r.id===b.dataset.export);downloadBlob('vibe-run-'+r.id+'.md',new Blob(['# '+(r.draft.objective||'Model result')+'\n\n'+r.output],{type:'text/markdown'}));});}
function render(){if(!state)return;const bits=location.hash.replace(/^#\/?/,'').split('/');route={page:bits[0]||'dashboard',id:bits[1],tab:bits[2]||'overview'};chrome();$('#main').className=route.tab==='design'?'studio-main':'';$('#main').innerHTML=route.page==='project'?(project()?projectPage(project()):'<div class="empty">Project not found. <a href="#/projects">Browse projects</a></div>'):route.page==='projects'?projectsPage():route.page==='archive'?projectsPage(true):route.page==='categories'?categories():route.page==='connections'?connections():dashboard();wire();}
let navigation=Promise.resolve();window.addEventListener('hashchange',()=>{navigation=navigation.then(async()=>{if(dirty)try{await saveDraft(true);}catch(e){toast(e.message);}clearTimeout(saveTimer);selected.clear();render();window.scrollTo(0,0);});});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{const r=await fetch(Vibe.base+'/studio-api/bootstrap',{headers:{Authorization:'Bearer '+Vibe.token}});if(!r.ok)throw Error('The workspace server is not running. Start Start-Vibe-Workspace.cmd in the project folder.');const b=await r.json();state=b.state;token=b.token;render();}catch(e){$('#main').innerHTML='<div class="empty"><h1>Let’s reconnect.</h1><p>'+esc(e.message)+'</p><p>Start <b>Start-Vibe-Workspace.cmd</b> from your project folder, then refresh.</p><a href="/design-studio.html">Open the existing Design Studio →</a></div>';}})();
